import{_ as a}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as t,c as o,a as s}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.12.0","description":"Mouse-driven TUI (click, double-click, scroll wheel), team re-pick/undo, query-title heading and matched token in output, and regex literal-quote fixes.","frontmatter":{"title":"What's new in v1.12.0","description":"Mouse-driven TUI (click, double-click, scroll wheel), team re-pick/undo, query-title heading and matched token in output, and regex literal-quote fixes.","date":"2026-08-23T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-12-0.md","filePath":"blog/release-v1-12-0.md"}`),n={name:"blog/release-v1-12-0.md"};function i(r,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="what-s-new-in-github-code-search-v1-12-0" tabindex="-1">What&#39;s new in github-code-search v1.12.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-12-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.12.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.12.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.12.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="mouse-support-in-the-interactive-tui" tabindex="-1">Mouse support in the interactive TUI <a class="header-anchor" href="#mouse-support-in-the-interactive-tui" aria-label="Permalink to &quot;Mouse support in the interactive TUI&quot;">​</a></h3><p>The TUI now responds to the terminal&#39;s SGR mouse protocol, alongside every existing keyboard shortcut:</p><ul><li><strong>Single-click</strong> on any row moves the cursor there (equivalent to <code>↑</code> / <code>↓</code>).</li><li><strong>Double-click</strong> on a repo&#39;s fold icon (<code>▸</code>/<code>▾</code>) toggles fold/unfold; double-click on the checkbox zone (columns 4+) toggles selection — on repos and extracts alike.</li><li><strong>Scroll wheel</strong> moves the viewport by 3 rows at a time.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ ✓ fulll/auth-service        ← double-click checkbox zone: toggle selection</span></span>
<span class="line"><span>  ✓ src/flags.ts:3:14         ← double-click: toggle extract selection</span></span></code></pre></div><p>During trackpad momentum scrolling, the TUI enters a brief &quot;scroll cooldown&quot; so residual clicks from a decelerating scroll gesture don&#39;t accidentally toggle a selection. Mouse and keyboard are fully complementary — everything remains reachable from the keyboard alone.</p><p>See <a href="/github-code-search/v2/reference/keyboard-shortcuts.html#mouse-support">Mouse support</a> for the full zone-by-zone reference.</p><h3 id="team-re-pick-mode-—-reassign-or-undo-a-pick" tabindex="-1">Team re-pick mode — reassign or undo a pick <a class="header-anchor" href="#team-re-pick-mode-—-reassign-or-undo-a-pick" aria-label="Permalink to &quot;Team re-pick mode — reassign or undo a pick&quot;">​</a></h3><p>Repos moved by <a href="/github-code-search/v2/usage/team-grouping.html#team-pick-mode">team pick mode</a> (marked <code>◈</code>) can now be reassigned, or restored back to their original combined section, directly from the TUI. Navigate to a picked repo and press <strong><code>t</code></strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>── squad-frontend</span></span>
<span class="line"><span>▶ ◈  fulll/frontend-app              ← press t here</span></span>
<span class="line"><span>▶ ◈  fulll/mobile-sdk</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>Re-pick: [ squad-frontend ]  squad-mobile  0/u restore  ← → move  ↵ confirm  Esc/t cancel</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> / <code>→</code></td><td>Cycle through candidate teams</td></tr><tr><td><code>Enter</code></td><td>Confirm and move the repo to the focused team</td></tr><tr><td><code>0</code> / <code>u</code></td><td>Undo the <strong>entire</strong> section pick — restore all its repos at once</td></tr><tr><td><code>Esc</code> / <code>t</code></td><td>Exit re-pick mode without changes</td></tr></tbody></table><p>Re-picks are interactive-only adjustments (not encoded in the replay command) — repeat them manually if you rerun the same query non-interactively.</p><h3 id="query-title-heading-and-matched-token-in-output" tabindex="-1">Query title heading and matched token in output <a class="header-anchor" href="#query-title-heading-and-matched-token-in-output" aria-label="Permalink to &quot;Query title heading and matched token in output&quot;">​</a></h3><p>Every output — Markdown and JSON, <code>repo-only</code> and <code>repo-and-matches</code> — now opens with a <code># Results for</code> heading identifying the query, plus qualifiers when active:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span># Results for &quot;useFeatureFlag&quot; · including archived · excluding templates</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3 repos · 4 files selected</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **fulll/auth-service** (2 matches)</span></span>
<span class="line"><span>  - [ ] [src/middlewares/featureFlags.ts:2:19](...): \`useFeatureFlag\`</span></span></code></pre></div><p>The exact matched token is now appended after each extract link in Markdown, and exposed as <code>matchedText</code> in JSON output when segment data is available. In <a href="/github-code-search/v2/usage/search-syntax.html#regex-queries">regex queries</a>, the heading shows the pattern in backticks instead: <code># Results for \`/useFeatureFlag/i\`</code>.</p><h3 id="regex-fixes-literal-quotes-and-safer-local-filtering" tabindex="-1">Regex fixes: literal quotes and safer local filtering <a class="header-anchor" href="#regex-fixes-literal-quotes-and-safer-local-filtering" aria-label="Permalink to &quot;Regex fixes: literal quotes and safer local filtering&quot;">​</a></h3><p>Several regex-mode edge cases are fixed in this release:</p><ul><li>Patterns containing literal <code>&quot;</code> characters (e.g. <code>/&quot;axios&quot;: &quot;[~^]?[0-9]&quot;/</code>) are now escaped automatically using GitHub&#39;s own quote-escaping syntax instead of being silently mangled when deriving the API search term.</li><li>Unbalanced double quotes in a plain-text query now <strong>fail fast</strong> locally with an actionable error instead of hitting GitHub&#39;s opaque <code>422 ERROR_TYPE_QUERY_PARSING_FATAL</code>.</li><li>Local regex filtering now falls back to the full file content when the API-returned fragment isn&#39;t enough to evaluate the pattern, fixing false negatives on multi-line matches.</li></ul><p>See <a href="/github-code-search/v2/usage/search-syntax.html#searching-for-a-literal-quote-character">Searching for a literal quote character</a> for the full escaping rules.</p><h3 id="bun-1-4-migration" tabindex="-1">Bun 1.4 migration <a class="header-anchor" href="#bun-1-4-migration" aria-label="Permalink to &quot;Bun 1.4 migration&quot;">​</a></h3><p>Internally, all ANSI/terminal handling (<code>stringWidth</code>, <code>stripANSI</code>, <code>sliceAnsi</code>) now goes through a single <code>render/terminal.ts</code> facade built on Bun 1.4&#39;s native APIs, and the TUI now handles live terminal resizes via <code>SIGWINCH</code> instead of requiring a restart. No user-facing behavior change, but more robust Unicode (graphemes, emoji, CJK) and layout handling.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div>`,28)])])}const k=a(n,[["render",i]]);export{f as __pageData,k as default};
